<script lang="ts">
	import { onMount } from 'svelte';
	import { Check, ClipboardList, Save } from '@lucide/svelte';
	import Panel from './BmsPanel.svelte';
	import Field from './BmsField.svelte';
	import Read from './BmsReadField.svelte';
	import { getBmsStringTelemetry, hasBmsSession, listBmsStrings, type BatteryString, type BmsStringTelemetry } from '$lib/services/bms-api';
	import { emptyBmsDeviceProfile, loadBmsAssetProfile, saveBmsAssetProfile, type BmsAssetProfile, type BmsDeviceProfile, type BmsSiteProfile } from '$lib/services/bms-asset-profile';
	let strings=$state<BatteryString[]>([]);let selectedIndex=$state(0);let telemetry=$state<BmsStringTelemetry|null>(null);let notice=$state('');let error=$state('');
	let profile=$state<BmsAssetProfile>({version:2,site:{owner:'',operationalTeam:'',substation:'',coordinates:'',maxicomSerial:''},devices:{}});
	let site=$state<BmsSiteProfile>({owner:'',operationalTeam:'',substation:'',coordinates:'',maxicomSerial:''});
	let device=$state<BmsDeviceProfile>(emptyBmsDeviceProfile());
	let loadedDeviceId=$state('');
	let selected=$derived(strings.find(s=>s.stringIndex===Number(selectedIndex))??strings[0]??null);let selectedId=$derived(selected?`str${selected.stringIndex}`:'');
	onMount(async()=>{try{profile=loadBmsAssetProfile();site={...profile.site};if(hasBmsSession()){strings=await listBmsStrings();selectedIndex=strings[0]?.stringIndex??0;loadDeviceDraft();await loadTelemetry();}}catch(e){error=e instanceof Error?e.message:'Failed to load asset data.'}});
	function retainDeviceDraft(){if(loadedDeviceId)profile.devices[loadedDeviceId]={...device}}
	function loadDeviceDraft(){retainDeviceDraft();loadedDeviceId=selectedId;device={...emptyBmsDeviceProfile(),...(profile.devices[selectedId]??{})}}
	async function selectDevice(){loadDeviceDraft();await loadTelemetry()}
	async function loadTelemetry(){if(!selectedId){telemetry=null;return}try{telemetry=await getBmsStringTelemetry(Number(selectedIndex))}catch{telemetry=null}}
	function save(){retainDeviceDraft();profile={version:2,site:{...site},devices:{...profile.devices}};saveBmsAssetProfile(profile);notice='Site and device information saved on this appliance.'}
	const fmt=(v:unknown,d=2)=>Number.isFinite(Number(v))?Number(v).toFixed(d):'N/A';
</script>
<section class="page"><div class="head"><div><h2><ClipboardList size={23}/>Asset Management</h2><p>Ownership, installation, technical configuration and battery test history.</p></div><button class="primary" onclick={save}><Save size={16}/>Save</button></div>{#if notice}<div class="notice"><Check size={16}/>{notice}</div>{/if}{#if error}<div class="error">{error}</div>{/if}
	<div class="wide shared"><Panel title="Site information — shared by all devices"><div class="grid shared-grid"><Field label="Owner" bind:value={site.owner}/><Field label="Operational team" bind:value={site.operationalTeam}/><Field label="Substation" bind:value={site.substation}/><Field label="Geographic coordinates" bind:value={site.coordinates}/><Field label="MAXiCom serial number" bind:value={site.maxicomSerial}/></div></Panel></div>
	<section class="device-records"><div><strong>Battery string records</strong><span>Select a string to edit only its device-specific information.</span></div><label>Battery string<select bind:value={selectedIndex} onchange={selectDevice}><option value={0}>No string selected</option>{#each strings as s}<option value={s.stringIndex}>str{s.stringIndex} — {s.stringName}</option>{/each}</select></label>{#if !hasBmsSession()}<span>Preview mode · data will load after BMS authentication</span>{/if}</section>
	<div class="two"><Panel title="Battery identity"><div class="grid"><Field label="DC level" bind:value={device.dcLevel}/><Field label="Battery bank / string ID" bind:value={device.batteryBankId}/></div></Panel><Panel title="Technical"><div class="grid"><Field label="Manufacturer" bind:value={device.manufacturer}/><label>Technologies<select bind:value={device.technology}><option value="">Select technology</option><option>AGM</option><option>GEL</option></select></label><Field label="Rated voltage" bind:value={device.normalVoltage}/><Read label="Capacity (Ah)" value={`${fmt(selected?.ratedCapacity)} Ah`}/><Read label="Cell / block count per string" value={selected?.cellQty??'N/A'}/></div></Panel></div>
	<div class="two"><Panel title="Manufacturing"><div class="grid"><Field label="Batch / lot number" bind:value={device.batchLotNumber}/><Field label="Manufacturing date" type="date" bind:value={device.manufacturingDate}/><Field label="Commissioning date" type="date" bind:value={device.commissioningDate}/></div></Panel><Panel title="Installation"><div class="grid"><Field label="Installation date" type="date" bind:value={device.installationDate}/><Field label="Responsible person" bind:value={device.responsiblePerson}/><Field label="Sensor mapping" bind:value={device.sensorMapping}/><label>Sensor calibration status<select bind:value={device.sensorCalibrationStatus}><option value="">Select status</option><option>Calibrated</option><option>Due for calibration</option><option>Not calibrated</option></select></label></div></Panel></div>
	<div class="wide"><Panel title="Charging"><div class="grid eval"><Read label="Float voltage" value={`${fmt(selected?.floatVoltage)} V`}/><Read label="Boost / equalize voltage" value={`${fmt(selected?.boostVoltage)} V`}/><Field label="Current limit (A)" type="number" bind:value={device.currentLimit}/></div></Panel></div>
	<div class="wide"><Panel title="Testing &amp; Health"><div class="grid health"><Field label="Voc" bind:value={device.testOcv}/><Field label="Float voltage" bind:value={device.testFloatVoltage}/><Field label="Internal resistance" bind:value={device.testIr}/><Field label="Temperature (negative terminal)" bind:value={device.testNegativeTerminalTemp}/><Read label="SOC" value={telemetry?.summary.stringSoC==null?'N/A':`${fmt(telemetry.summary.stringSoC,1)} %`}/><Read label="SOH" value={telemetry?.summary.stringSoH==null?'N/A':`${fmt(telemetry.summary.stringSoH,1)} %`}/><Field label="SOH warning limit (%)" type="number" bind:value={device.sohWarningThreshold}/><Field label="SOH replacement limit (%)" type="number" bind:value={device.sohReplaceThreshold}/><Field label="Planned replacement date" type="date" bind:value={device.replacementDate}/></div></Panel></div>
</section>
<style>
	.page{animation:in .18s ease}.head{display:flex;justify-content:space-between;gap:18px;margin-bottom:18px}.head h2{display:flex;align-items:center;gap:9px;margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 0;color:#718096;font-size:16px}.primary{display:inline-flex;align-items:center;gap:7px;height:39px;padding:0 14px;border:0;border-radius:8px;color:#fff;background:#1749ad;font:inherit;cursor:pointer}.device-records{display:flex;align-items:end;justify-content:space-between;gap:18px;margin-bottom:15px;padding:14px 17px;border:1px solid #e1e7f0;border-radius:11px;background:#fff}.device-records>div{display:grid;gap:5px}.device-records>div strong{color:#30425e;font-size:15px;font-weight:600}.device-records>div span,.device-records>span{color:#7b8799;font-size:12px}.device-records label{min-width:260px}.two{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:15px}.wide{margin-bottom:15px}.shared-grid{grid-template-columns:repeat(5,minmax(0,1fr))!important}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px 14px}.grid.eval,.grid.health{grid-template-columns:repeat(3,minmax(0,1fr))}label{display:grid;gap:6px;color:#536078;font-size:13px}input,select{width:100%;height:39px;padding:0 11px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit;font-size:14px}input:disabled{color:#718096;background:#f5f7fa}.notice,.error{margin-bottom:13px;padding:10px 12px;border-radius:8px;font-size:13px}.notice{display:flex;align-items:center;gap:7px;color:#28784e;background:#f2fbf5;border:1px solid #cae7d5}.error{color:#b42318;background:#fff1f0;border:1px solid #f3cac6}@keyframes in{from{opacity:0;transform:translateY(4px)}}@media(max-width:1200px){.shared-grid{grid-template-columns:repeat(3,minmax(0,1fr))!important}}@media(max-width:950px){.two{grid-template-columns:1fr}.grid.eval,.grid.health,.shared-grid{grid-template-columns:1fr 1fr!important}}@media(max-width:650px){.head{flex-direction:column}.head .primary{justify-content:center}.grid,.grid.eval,.grid.health,.shared-grid{grid-template-columns:1fr!important}.device-records{align-items:stretch;flex-direction:column}.device-records label{min-width:0}}
</style>
